  $('.page-heading').hidden=v!=='overview';
  $('#workspaceHeading').hidden=!['library','shortlist','assistant'].includes(v);
  $('#workspaceTitle').textContent={library:activeRun?`Results - ${activeRun.configuration?.virusName||activeRun.virus}`:'AI Screening Results',shortlist:'Your saved compounds',assistant:'Ask fairuz AI'}[v]||'';
  $('#workspaceDescription').textContent={library:'Compare ranked predictions and explore each compound in 3D.',shortlist:'Return to the candidates you saved in this browser.',assistant:'Understand this study through answers drawn from its existing evidence.'}[v]||'';
  $('#overview').hidden=!['overview','library','shortlist','assistant'].includes(v);
  $('#intro').hidden=v!=='overview';$('.stats').hidden=v!=='overview';$('.main-grid').hidden=v!=='overview';
