async function loadModel(key){if(modelCache[key])return modelCache[key];const res=await fetch(`models/${key}.json`);if(!res.ok)throw new Error(`Model download failed (${res.status}).`);const text=await res.text();const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text));const hash=Array.from(new Uint8Array(digest),x=>x.toString(16).padStart(2,'0')).join('');if(hash!==study.models[key].artifactSha256)throw new Error('Model artifact hash mismatch. Reload the study before screening.');const model=JSON.parse(text);modelCache[key]=model;return model}
