async function runReferenceBatch(configuration,{withSummary=false}={}){
 const targets=referenceTargets(study);if(!targets.length)throw new Error('No supported reference target models are installed. No screening was run.');
 const candidates=configuration.library==='focused'?study.library.slice().sort((a,b)=>a.id.localeCompare(b.id)).slice(0,60):study.library;
 const sessionId=`FZ-DEMO-${Date.now().toString(36).toUpperCase()}`,completed=[],failed=[];
 for(const [index,{key,model:meta}] of targets.entries()){
  $('#progress').textContent=`Screening reference target ${index+1} of ${targets.length}: ${meta.target}...`;
  await new Promise(resolve=>setTimeout(resolve,30));
  try{
   const model=await loadModel(key);
   const ranked=rankCandidates(model,candidates,study.trainingReferences).map(c=>({...c,assayPlaceholder:makeAssayPlaceholder(c.id,key)}));
   if(!ranked.length||ranked.some(c=>!Number.isFinite(c.prediction)))throw new Error('The model returned no valid predictions.');
   const run={id:`${sessionId}-${key}`,sessionId,timestamp:new Date().toISOString(),key,virus:meta.virus,target:meta.target,modelId:meta.id,artifactSha256:meta.artifactSha256,candidateCount:ranked.length,endpoint:'Predicted synthetic pIC50; descending within this reference target only',scoreUnits:'synthetic pIC50',uncertaintyLabel:'Tree SD',library:configuration.library==='focused'?'Pilot: first 60 candidate IDs':'Full unseen candidate library',synthetic:true,model:meta,configuration:JSON.parse(JSON.stringify(configuration)),mode:'synthetic-reference-batch',customVirusInference:false,summary:null};
   completed.push({run,rows:ranked});
  }catch(error){failed.push({key,target:meta.target,error:error.message});}
 }
 if(!completed.length)throw new Error('No reference targets could be screened. No new results were created. '+failed.map(f=>f.target+': '+f.error).join(' '));
 const available=completed.map(entry=>({key:entry.run.key,label:entry.run.target,referenceVirus:entry.run.virus}));
 for(const entry of completed){entry.run.availableTargets=available;entry.run.failedTargets=failed;audit.push({...entry.run,model:undefined,summary:undefined});}
 audit=audit.slice(-100);persist();targetSessions=completed;targetSwitcher.hidden=false;
 const select=$('#activeReferenceTarget');select.replaceChildren();for(const target of available){const option=document.createElement('option');option.value=target.key;option.textContent=target.label+' - '+target.referenceVirus;select.append(option);}
 activateReferenceTarget(completed[0].run.key,{reveal:true});
 if(failed.length){$('#loadError').hidden=false;$('#loadError').textContent=`${completed.length} of ${targets.length} reference targets completed. Unavailable targets: `+failed.map(f=>f.target+': '+f.error).join(' ');}
 if(withSummary)setTimeout(()=>generateSummary(),0);
 return {completed:completed.length,failed:failed.length,sessionId};
}
